  (slug, name, type, tagline, description, website, city, state, sector, industry, stage, founded, founders, investors, funding, lat, lng, timing, status)
values
('titan-capital', 'Titan Capital', 'vc', 'Seed fund of Snapdeal founders Kunal Bahl and Rohit Bansal — early backer of Razorpay, OYO.', 'Founded in 2015 by the Snapdeal co-founders. Leads early rounds with cheques of roughly $300–500K and decides fast. Over 300 portfolio companies, which have produced 8 unicorns, 4 IPOs and 26 acquisitions. Supportive of tech-enabled food chains and retail innovation. Notable portfolio: Ola, Razorpay, Mamaearth, Urban Company, Chaayos.', 'https://www.titancapital.vc', 'Gurugram', 'Delhi NCR', 'Family Office', 'QSR, FoodTech, Consumer Retail', 'Pre-Seed to Seed', '2015', 'Kunal Bahl, Rohit Bansal', '', '', 28.4711, 77.0301, '', 'live'),
('jsw-ventures', 'JSW Ventures', 'vc', 'Early-stage venture arm of the JSW Group backing technology-led businesses.', '', 'https://www.jswventures.in', 'Mumbai', 'Maharashtra', 'CVC', '', '', '2016', '', '', '', 19.11194, 72.92746, '', 'live'),
('sauce-vc', 'Sauce.vc', 'vc', 'Consumer Micro-VC backing qsr, cloud kitchens, f&b, retail.', 'Delhi-based consumer fund founded in 2019, entering as early as pre-seed and following on through later rounds via separate early-stage and opportunities funds. Around ₹850 crore of committed capital. Focuses on nimble F&B formats, QSR brands and direct-to-consumer food products. Typical cheque size ₹2.0–₹15.0 crore. Notable consumer portfolio: Mokobara, The Whole Truth Foods, Epigamia, XYXX, Hocco Ice Creams, Innovist.', 'https://www.sauce.vc', 'Delhi', 'Delhi NCR', 'Micro PE / VC', 'QSR, Cloud Kitchens, F&B, Retail', 'Pre-Seed to Seed', '2019', 'Manu Chandra', '', '', 28.62604, 77.20186, '', 'live'),
('gruhas', 'Gruhas', 'vc', 'Multi Family Office / VC backing retail, f&b, consumer, proptech.', 'Bengaluru investment firm co-founded in 2021 by Zerodha''s Nikhil Kamath and Abhijeet Pai of the Puzzolana Group. Invests at seed and Series A across climate tech, consumer brands, senior care, sustainability and proptech, with around 68 portfolio companies. Also runs the ₹300 crore Earth Fund with Brigade Group. Typical cheque size ₹3.0–₹20.0 crore. Notable portfolio: Licious, Epoch Elder Care.', 'https://www.gruhas.com', 'Bengaluru', 'Karnataka', 'Family Office', 'Retail, F&B, Consumer, PropTech', 'Seed to Series A', '2021', 'Nikhil Kamath, Abhijeet Pai', '', '', 12.95316, 77.64091, '', 'live'),
('anicut-capital', 'Anicut Capital', 'vc', 'Early VC & Angel Fund backing qsr, f&b, retail, dining tech.', 'Founded in Chennai in 2015. Runs a full-spectrum platform of seed equity, venture debt and private credit for profitable consumer brands and SMEs — useful to F&B and QSR formats needing working capital and capex alongside equity. Around ₹4,500 crore across debt and equity strategies. Typical cheque size ₹2.0–₹20.0 crore. Notable portfolio: Bira 91, WOW! Momo, SUGAR Cosmetics, Earth Rhythm, ShareChat.', 'https://www.anicutcapital.com', 'Chennai', 'Tamil Nadu', 'VC Funds', 'QSR, F&B, Retail, Dining Tech', 'Seed to Series A', '2015', 'Ashvin Chadha, IAS Balamurugan', '', '', 13.10776, 80.26575, '', 'live'),
('narotam-sekhsaria-family-office', 'Narotam Sekhsaria Family Office', 'vc', 'Single Family Office backing consumer retail, f&b, d2c.', 'Single family office of the Ambuja Cements co-founder, established in 2006 after the Holcim sale. Over $1bn under management across public markets, commodities, private equity and real estate, with global operations. Invests directly in Indian startups and as a limited partner in domestic venture funds, favouring long-term partnerships with strong leadership teams. Typical cheque size ₹5.0–₹20.0 crore.', 'https://www.nsfo.in', 'Mumbai', 'Maharashtra', 'Family Office', 'Consumer Retail, F&B, D2C', 'Seed to Series A', '2006', 'Pulkit Sekhsaria, Padmini Somani', '', '', 19.04867, 72.92621, '', 'live'),
('patni-financial-advisors-pfa', 'Patni Financial Advisors (PFA)', 'vc', 'Single Family Office backing consumer brands, foodtech, retail.', 'Mumbai single family office of the Patni Computer Systems family, founded in 2005 and active in venture investing after the 2011 sale of the business. Deploys across listed securities, private equity, debt, real estate and other alternatives in India and internationally, with retail, software, media and healthcare technology the largest private allocations. Typical cheque size ₹2.0–₹15.0 crore. Notable portfolio: Innoviti, FAE Beauty, Bombay Shaving Company.', 'https://www.patnifa.com', 'Mumbai', 'Maharashtra', 'Family Office', 'Consumer Brands, FoodTech, Retail', 'Seed to Pre-Series A', '2005', 'Arihant Patni', '', '', 19.05908, 72.92153, '', 'live'),
('catamaran-ventures', 'Catamaran Ventures', 'vc', 'Single Family Office backing consumer retail, f&b, supply chain.', 'N.R. Narayana Murthy''s family office, established in Bengaluru in 2009. Invests across public equity, private equity and growth-stage venture capital, with a stated focus on growth capital for Indian manufacturing. Backs scalable consumer and retail models with disciplined operations and strong governance. Around 49 portfolio companies. Typical cheque size ₹5.0–₹20.0 crore. Notable consumer portfolio: Paper Boat (Hector Beverages), Cloudtail.', 'https://catamaran.in', 'Bengaluru', 'Karnataka', 'Family Office', 'Consumer Retail, F&B, Supply Chain', 'Seed to Series A', '2009', 'Deepak Padaki (President), N.R. Narayana Murthy (Chairman Emeritus)', '', '', 13.02013, 77.63688, '', 'live'),
('108-capital', '108 Capital', 'vc', 'Growth-stage venture fund', 'Growth-stage venture fund. It partners with founders to build digital-first and sustainable businesses.', 'https://108.vc', 'Mumbai', 'Maharashtra', 'VC Funds', '', 'Growth', '2023', 'Sushma Kaushik (Founding Partner); Nimesh Kampani (Founding Partner)', '', '', 19.08274, 72.8827, '', 'live'),
('3i-partners', '3i Partners', 'vc', 'Venture capital investment fund', 'Venture capital investment fund. It funds disruptive deep-tech innovations from India. Its primary investment areas include Tech Bio, Climate Tech, and Frontier Tech, aligning with our mission to support innovations that enhance global health, safety, and efficiency. It We invest in companies raising Pre-seed, Seed, and Pre-Series A funding rounds. It invest in transformative technologies with the aim to create a healthier, safer, and more efficient world. Its philosophy centers on supporting visionary founders who disrupt industries with innovative technologies and scalable business models.', 'https://www.3ipartners.vc', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Pre-seed to Seed', '2020', 'Rajiv Parikh (Partner); Kumar Ganapathy (Founder & Managing Director); Arvind Kannan (CTO); Ravi Mistry (Founding Team Member & Venture Partner)', '', '', 13.0117, 77.64378, '', 'live'),
('abell-ventures', 'Abell Ventures', 'vc', 'Platform offering solutions to startups', 'Platform offering solutions to startups. It provides provides a platform for startups that works closely with budding entrepreneurs and helps transform their ideas into businesses', 'http://abellventures.com', 'Bengaluru', 'Karnataka', 'VC Funds', '', '', '2024', 'Anil Neglur (Co-Founding Partner); Kishore Purohit (Co-Founding Partner)', '', '', 13.00721, 77.63415, '', 'live'),
('alpha-wave-global', 'Alpha Wave Global', 'vc', 'Venture capital firm focused on growth-stage companies', 'Venture capital firm focused on growth-stage companies. It focuses on a number of asset classes and geographies, ranging from venture and growth to public markets to credit.', 'https://www.alphawaveglobal.com', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Growth', '', 'Bin Li (Director); Rick Gerson (Co-Founder, Chairman & CIO); Navroz D Udwadia (Co-Founder); Ryan Khoury (Co-Founder & Partner)', '', '', 13.01351, 77.59585, '', 'live'),
('altinvest-capital-advisors', 'AltInvest Capital Advisors', 'vc', 'Venture capital investment firm', 'Venture capital investment firm. It helps investors generate returns from high-yield securities in the Indian market. It focus on early-stage investments, provide supports to entrepreneurs and startups in various sectors, including technology and finance.', 'https://www.altcapital.ai', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Seed to Series A', '2018', 'Dirk Van Quaquebeke (Board Member); Kunal Moktan (Co-Founder & CEO); Hashim Khan (Co Founder & CTO); Deepak Ramineedi (Board Member)', '', '', 12.93822, 77.57103, '', 'live'),
('athera', 'Athera', 'vc', 'Early-stage venture capital firm investing in sustainable, tech-first ventures', 'Early-stage venture capital firm investing in sustainable, tech-first ventures. The firm partners with entrepreneurs, providing support and guidance throughout the company''s growth. Investment focus is on businesses with potential for long-term success, even after the firm''s involvement. A key aspect of their approach is maintaining transparent and unbiased interactions with portfolio companies. They prioritize building lasting relationships with founders.', 'https://www.atheravp.com', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Seed to Series A', '2008', 'Samir Kumar (Managing Director & General Partner); Abdul Qadir Abdul Rahman Buhari (Limited Partner); Rajiv Mehta (Managing Director & General Partner); Parag Dhol (General Partner)', '', '', 12.9225, 77.63809, '', 'live'),
('austin-global-ventures', 'Austin Global Ventures', 'vc', 'Venture capital investment firm', 'Venture capital investment firm. It aims to connect innovative ideas and experiences to accelerate ecosystem growth.', 'https://austingv.com', 'Bengaluru', 'Karnataka', 'VC Funds', '', '', '2014', 'Nithin Kamath (Director); Austin Prakesh (Director)', '', '', 12.99521, 77.63936, '', 'live'),
('avataar-ventures', 'Avataar Ventures', 'vc', 'Venture capital firm focused on growth equity', 'Venture capital firm focused on growth equity. It is an operational fund that partners with tech-led B2B and SaaS startups to transform into businesses. It provides growth capital so that companies can focus on their core business instead of fund-raising.', 'http://avataar.vc', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Growth', '2019', 'Mike Mulica (Operating Partner); Rana Gujral (Operating Partner); Mohan Kumar (Founder & Managing Partner); Nishant Rao (Founding Partner)', '', '', 12.9656, 77.56086, '', 'live'),
('betonindia', 'BetOnIndia', 'vc', 'BetOnIndia Technology is a venture capital investment company', 'BetOnIndia Technology is a venture capital investment company. Invests in geographies like India. Typically invests in tech companies specializing in areas like FashionTech, Security. Notable portfolio companies include CareVision, Fracktal Works, Duffl.', 'https://betonindia.in', 'Bengaluru', 'Karnataka', 'VC Funds', '', '', '2015', 'Chandru Bolaki (Founder, CEO & Managing Director)', '', '', 12.93518, 77.57101, '', 'live'),
('beyond-next-ventures', 'Beyond Next Ventures', 'vc', 'Provider of seed-stage funding and incubation for deep-tech startups', 'Provider of seed-stage funding and incubation for deep-tech startups. It is a venture capital firm specializing in seed- and early-stage deep-tech investments. It supports startups in healthcare, biotechnology, agritech/foodtech, digital technologies, space, and climate tech. The team guides founders from formation through exits, and build ecosystems via capital, talent development, and shared wet-lab facilities', 'https://beyondnextventures.com', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Seed to Series A', '2014', 'Jay Krishnan (Partner); Tsuyoshi Ito (Co-Founder, CEO, President, Founding Partner & Managing Partner); Kengo Ueha (Co-Founder & Partner); Katsuya Hashizume (Patner)', '', '', 12.98486, 77.54608, '', 'live'),
('bharat-innovation-fund', 'Bharat Innovation Fund', 'vc', 'Venture capital fund focused on tech startups', 'Venture capital fund focused on tech startups. It invests at early-stage in IP-driven Indian startups across sectors such as healthcare, agriculture, renewables, and advanced technology.', 'https://bharat.fund', 'Ahmedabad', 'Gujarat', 'VC Funds', '', 'Seed to Series A', '2017', 'Sanjay Jain (Partner); Sanea Vakaliya (Chief Financial Officer); Abdul Qadir Abdul Rahman Buhari (Limited Partner); Kunal Upadhyay (Co-Founder, Managing Partner & Investment Committee Member)', '', '', 23.03643, 72.53435, '', 'live'),
('bitkemy-technologies', 'Bitkemy Technologies', 'vc', 'BitKemy Ventures is a incubators and venture capital firm that invests in seed stage companies primarily in India', 'BitKemy Ventures is a incubators and venture capital firm that invests in seed stage companies primarily in India. It invests in tech companies operating in sectors Enterprise Tech, SaaS, HealthTech, FinTech & E-Commerce. Notable portfolio companies include Altiux, 3LOQ, Shotang, eKincare, etc.', 'https://bitkemy.com', 'Hyderabad', 'Telangana', 'VC Funds', '', 'Seed to Series A', '2012', 'Sridhar Ponnuru (General Manager); Sunil Motaparti (Founder & Director)', '', '', 17.4671, 78.49349, '', 'live'),
('byt-capital', 'BYT Capital', 'vc', 'Investor in early-stage deep-tech companies', 'Investor in early-stage deep-tech companies. This firm funds science-led ventures from pre-seed to Series A, focusing on advanced technology and scientific research across sectors such as data analytics, agritech, machine learning, and biotechnology. Beyond financial investment, it provides strategic guidance, operational expertise, and access to extensive networks to support portfolio companies through the entire innovation cycle. The investment approach prioritizes long- term partnerships and hands-on support to help companies achieve scale.', 'https://www.bytcapital.in', 'Bengaluru', 'Karnataka', 'VC Funds', '', 'Pre-seed to Seed', '2025', 'Amit Chand (Managing Partner); Dinesh Singh (Partner); Karan Verma (Partner)', '', '', 12.991, 77.59391, '', 'live'),
('cactus-venture-partners', 'Cactus Venture Partners', 'vc', 'Venture capital focused on early-stage investments', 'Venture capital focused on early-stage investments. It mainly invests in climate tech, health tech, B2B SaaS, and Direct-to-customer businesses, and more.', 'https://cactusvp.com', 'Mumbai', 'Maharashtra', 'VC Funds', '', 'Seed to Series A', '2020', 'Rajeev Kalambi (General Partner); Amit Sharma (General Partner); Anurag Goel (General Partner); Baskaran Kesavareddiyar (Director)', '', '', 19.04526, 72.9258, '', 'live'),
